Theorem impl_run_safe2 : node_sound -> forall {R} (t : itree R) Q ms mo,
  impl t Q ms -> leaves_unreachable_m t mo -> m_halted mo = None -> minv mo -> tsafe t mo ->
  ms_svc_pending ms = None ->
